import '@servicenow/sdk/global'
import { action, Subflow, wfa, FlowObject, FlowArray } from '@servicenow/sdk/automation'
import { BooleanColumn, DateTimeColumn, IntegerColumn, StringColumn } from '@servicenow/sdk/core'

/**
 * Comprehensive Test Subflow for FlowObject and FlowArray in assignSubflowOutputs
 * This mirrors the setFlowVariables test to verify all scenarios work correctly.
 */
export const testSubflowComplexOutputs = Subflow(
    {
        $id: Now.ID['test_subflow_complex_outputs'],
        name: 'Test Subflow - Complex Outputs',
        description: 'Subflow with FlowObject and FlowArray outputs for testing',
        inputs: {
            inputData: StringColumn({ label: 'Input Data', mandatory: false }),
            userEmail: StringColumn({ label: 'User Email', mandatory: false }),
            userAge: IntegerColumn({ label: 'User Age', mandatory: false }),
        },
        outputs: {
            // Simple FlowObject output
            userInfo: FlowObject({
                fields: {
                    name: StringColumn({ label: 'Name', mandatory: false }),
                    email: StringColumn({ label: 'Email', mandatory: false }),
                    age: IntegerColumn({ label: 'Age', mandatory: false }),
                    isActive: BooleanColumn({ label: 'Is Active', mandatory: false }),
                },
                label: 'User Info',
                mandatory: false,
            }),

            // Simple FlowArray (FlowObject elements)
            tags: FlowArray({
                label: 'Tags',
                mandatory: false,
                elementType: FlowObject({
                    fields: {
                        value: StringColumn({ label: 'Tag Value', mandatory: false }),
                    },
                    label: 'Tag',
                    mandatory: false,
                }),
                childName: 'tag',
            }),

            // Nested FlowObject
            config: FlowObject({
                fields: {
                    settings: FlowObject({
                        fields: {
                            timeout: IntegerColumn({ label: 'Timeout', mandatory: false }),
                            retries: IntegerColumn({ label: 'Retries', mandatory: false }),
                            enabled: BooleanColumn({ label: 'Enabled', mandatory: false }),
                        },
                        label: 'Settings',
                        mandatory: false,
                    }),
                    description: StringColumn({ label: 'Description', mandatory: false }),
                },
                label: 'Config',
                mandatory: false,
            }),

            // FlowObject with nested FlowArray
            project: FlowObject({
                fields: {
                    name: StringColumn({ label: 'Project Name', mandatory: false }),
                    tasks: FlowArray({
                        label: 'Tasks',
                        mandatory: false,
                        elementType: FlowObject({
                            fields: {
                                taskName: StringColumn({ label: 'Task Name', mandatory: false }),
                            },
                            label: 'Task',
                            mandatory: false,
                        }),
                        childName: 'task',
                    }),
                },
                label: 'Project',
                mandatory: false,
            }),

            // FlowObject for testing empty/null values
            partialData: FlowObject({
                fields: {
                    field1: StringColumn({ label: 'Field 1', mandatory: false }),
                    field2: StringColumn({ label: 'Field 2', mandatory: false }),
                    field3: IntegerColumn({ label: 'Field 3', mandatory: false }),
                },
                label: 'Partial Data',
                mandatory: false,
            }),

            // FlowObject for testing datapill assignment
            callerData: FlowObject({
                fields: {
                    userId: StringColumn({ label: 'User ID', mandatory: false }),
                    userName: StringColumn({ label: 'User Name', mandatory: false }),
                },
                label: 'Caller Data',
                mandatory: false,
            }),

            // FlowArray for testing empty array
            emptyList: FlowArray({
                label: 'Empty List',
                mandatory: false,
                elementType: FlowObject({
                    fields: {
                        item: StringColumn({ label: 'Item', mandatory: false }),
                    },
                    label: 'List Item',
                    mandatory: false,
                }),
                childName: 'listItem',
            }),

            // FlowObject for testing mixed literals and datapills
            mixedData: FlowObject({
                fields: {
                    staticValue: StringColumn({ label: 'Static Value', mandatory: false }),
                    dynamicValue: StringColumn({ label: 'Dynamic Value', mandatory: false }),
                    computedValue: StringColumn({ label: 'Computed Value', mandatory: false }),
                },
                label: 'Mixed Data',
                mandatory: false,
            }),

            // FlowObject with primitive FlowArrays (nested primitive arrays)
            dataCollection: FlowObject({
                fields: {
                    title: StringColumn({ label: 'Title', mandatory: false }),
                    stringList: FlowArray({
                        label: 'String List',
                        mandatory: false,
                        elementType: StringColumn({ label: 'String Item', mandatory: false }),
                        childName: 'stringItem',
                    }),
                    numberList: FlowArray({
                        label: 'Number List',
                        mandatory: false,
                        elementType: IntegerColumn({ label: 'Number Item', mandatory: false }),
                        childName: 'numberItem',
                    }),
                    booleanList: FlowArray({
                        label: 'Boolean List',
                        mandatory: false,
                        elementType: BooleanColumn({ label: 'Boolean Item', mandatory: false }),
                        childName: 'booleanItem',
                    }),
                    dateList: FlowArray({
                        label: 'Date List',
                        mandatory: false,
                        elementType: DateTimeColumn({ label: 'Date Item', mandatory: false }),
                        childName: 'dateItem',
                    }),
                },
                label: 'Data Collection',
                mandatory: false,
            }),

            // Simple string output for comparison
            simpleString: StringColumn({ label: 'Simple String', mandatory: false }),
        },
    },
    (params) => {
        // ==== TEST 1: Happy Path - Object literals ====
        wfa.flowLogic.assignSubflowOutputs(
            { $id: Now.ID['test1_assign_literals'], annotation: 'TEST 1: Literals' },
            params.outputs,
            {
                userInfo: { name: 'John Doe', email: 'john@example.com', age: 30, isActive: true },
                tags: [{ value: 'urgent' }, { value: 'important' }],
                simpleString: 'Test completed',
            }
        )

        // ==== TEST 2: Datapills in FlowObject fields ====
        wfa.flowLogic.assignSubflowOutputs(
            { $id: Now.ID['test2_assign_datapills'], annotation: 'TEST 2: Datapills' },
            params.outputs,
            {
                userInfo: {
                    name: wfa.dataPill(params.inputs.inputData, 'string'),
                    email: wfa.dataPill(params.inputs.userEmail, 'string'),
                    age: wfa.dataPill(params.inputs.userAge, 'integer'),
                    isActive: true,
                },
            }
        )

        // ==== TEST 3: Nested FlowObject ====
        wfa.flowLogic.assignSubflowOutputs(
            { $id: Now.ID['test3_assign_nested'], annotation: 'TEST 3: Nested' },
            params.outputs,
            {
                config: {
                    settings: { timeout: 60, retries: 5, enabled: true },
                    description: 'Production',
                },
            }
        )

        // ==== TEST 4: FlowObject with nested FlowArray ====
        wfa.flowLogic.assignSubflowOutputs(
            { $id: Now.ID['test4_assign_nested_array'], annotation: 'TEST 4: Nested Array' },
            params.outputs,
            {
                project: {
                    name: 'Infrastructure',
                    tasks: [{ taskName: 'Setup' }, { taskName: 'Configure' }],
                },
            }
        )

        // ==== TEST 5: Empty FlowArray ====
        wfa.flowLogic.assignSubflowOutputs(
            { $id: Now.ID['test5_assign_empty_array'], annotation: 'TEST 5: Empty Array' },
            params.outputs,
            {
                emptyList: [],
            }
        )

        // ==== TEST 6: Template expressions ====
        wfa.flowLogic.assignSubflowOutputs(
            { $id: Now.ID['test6_assign_template'], annotation: 'TEST 6: Template' },
            params.outputs,
            {
                mixedData: {
                    staticValue: 'Static',
                    dynamicValue: wfa.dataPill(params.inputs.inputData, 'string'),
                    computedValue: `Result: ${wfa.dataPill(params.inputs.inputData, 'string')}`,
                },
            }
        )

        // ==== TEST 7: FlowObject with primitive FlowArrays ====
        wfa.flowLogic.assignSubflowOutputs(
            { $id: Now.ID['test7_assign_nested_primitive_arrays'], annotation: 'TEST 7: Nested Primitive Arrays' },
            params.outputs,
            {
                dataCollection: {
                    title: 'Sample Data Collection',
                    stringList: ['apple', 'banana', 'cherry'],
                    numberList: [10, 20, 30],
                    booleanList: [true, false, true],
                    dateList: ['2024-01-01 10:00:00', '2024-06-15 14:30:00'],
                },
            }
        )

        // ==== TEST 8: FlowObject with primitive FlowArrays and datapills ====
        wfa.flowLogic.assignSubflowOutputs(
            { $id: Now.ID['test8_assign_nested_arrays_datapills'], annotation: 'TEST 8: Nested Arrays with Datapills' },
            params.outputs,
            {
                dataCollection: {
                    title: wfa.dataPill(params.inputs.inputData, 'string'),
                    stringList: ['static', wfa.dataPill(params.inputs.inputData, 'string')],
                    numberList: [100, wfa.dataPill(params.inputs.userAge, 'integer')],
                    booleanList: [true],
                    dateList: ['2024-12-31 23:59:59'],
                },
            }
        )

        // Log completion
        wfa.action(
            action.core.log,
            { $id: Now.ID['log_complete'] },
            { log_level: 'info', log_message: 'All assignSubflowOutputs tests completed' }
        )
    }
)
